code='''from collections import deque
def transform(grid):
    out=[r[:] for r in grid]
    color=next(v for row in grid for v in row if v not in (0,9))
    h,w=len(grid),len(grid[0]); seen=set()
    for r in range(h):
      for c in range(w):
        if grid[r][c]!=0 or (r,c) in seen: continue
        q=[(r,c)]; seen.add((r,c)); comp=[]
        for x,y in q:
          comp.append((x,y))
          for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
            if 0<=nx<h and 0<=ny<w and grid[nx][ny]==0 and (nx,ny) not in seen:
              seen.add((nx,ny)); q.append((nx,ny))
        if len(comp)>=3:
          for x,y in comp: out[x][y]=color
    return out
'''
